var typeValues = [3, 2, 8, 11];
var currentType = typeValues[idx] !== undefined ? typeValues[idx] : 3;
var books = [];
for (var i = 0; i < tabs.length; i++) {
    if (tabs[i].tab_type == currentType && tabs[i].data) {
        for (var j = 0; j < tabs[i].data.length; j++) {
            var g = tabs[i].data[j];
            if (currentType == 11) {
                // === 短剧: 从 video_data 取, 统一成书结构 ===
                var vd = g.video_data;
                if (vd) {
                    for (var k = 0; k < vd.length; k++) {
                        var it = vd[k];
                        var cat = '';
                        try {
                            var cs = JSON.parse(it.category_schema || '[]');
                            if (cs[0]) cat = cs[0].name;
                        } catch (e) {}
                        books.push(JSON.stringify({
                            book_name: it.title || it.raw_book_name || '',
                            author: it.author || '',
                            category: cat,
                            abstract: it.rec_text || it.sub_title || '',
                            thumb_url: it.cover || it.horiz_cover || '',
                            book_id: it.series_id || it.vid || ''
                        }));
                    }
                }
            } else {
                // === 小说/听书/漫画: 原有逻辑 ===
                var bd = g.book_data;
                if (bd) {
                    for (var k = 0; k < bd.length; k++) {
                        books.push(JSON.stringify(bd[k]));
                    }
                }
            }
        }
    }
}
