var LR_LOGIN_FIELDS=[
  {name:"token",key:"token"},
  {name:"imei",key:"imei"},
  {name:"nwt",key:"nwt"},
  {name:"mode",key:"mode"},
  {name:"lrid",key:"lrid"},
  {name:"ostar36",key:"ostar36"},
  {name:"userMode",key:"userMode"},
  {name:"duId",key:"duId"}
];

function lrtsLoginField(name){
  try{
    if(result&&typeof result.get==="function")return String(result.get(name)||"").trim();
  }catch(e1){}
  try{
    if(result&&result[name]!==null&&result[name]!==undefined)return String(result[name]).trim();
  }catch(e2){}
  return "";
}

function login(){
  var session={};
  var missing=[];
  LR_LOGIN_FIELDS.forEach(function(field){
    var value=lrtsLoginField(field.name);
    if(!value)missing.push(field.name);
    session[field.key]=value;
  });
  if(missing.length){
    java.longToast("请完整填写以下参数：\n"+missing.join("、"));
    return;
  }
  source.put("lrts_session",JSON.stringify(session));
  source.put("lrts_q","0");
  try{
    var map=new Packages.java.util.HashMap();
    LR_LOGIN_FIELDS.forEach(function(field){map.put(field.name,session[field.key]);});
    java.upLoginData(map);
  }catch(saveError){}
  java.longToast("个人 App 会话已保存并启用");
}

