function __enc(x) {
  return encodeURIComponent(x).replace(/[!'()*]/g, function(c) {
    return '%' + c.charCodeAt(0).toString(16).toUpperCase();
  });
}

(function() {
  var host = "https://www.rrssk.com";

  var homeHtml = String(java.ajax(host + "/0005.html"));

  var signJsMatch = homeHtml.match(/\/\?action=signJs&v=[^"']+/);
  if (!signJsMatch) {
    // java.log("[-] 未找到 signJs URL");
    return;
  }
  var signJsUrl = host + signJsMatch[0];
  // java.log("[+] signJsUrl = " + signJsUrl);

  var verMatch = signJsUrl.match(/v=(\d+-\d+)/);
  var version = verMatch ? verMatch[1] : "default";

  var tMatch = homeHtml.match(/name="_t" value="([^"]+)"/);
  var t = tMatch ? tMatch[1] : null;
  if (!t) {
    // java.log("[-] 未找到 _t");
    return;
  }
  // java.log("[+] _t = " + t);

  var cacheKey = "rrssk_signJs";
  var signJsCode = null;
  var cachedRaw = cache.get(cacheKey);

  if (cachedRaw) {
    try {
      var cached = JSON.parse(cachedRaw);
      if (cached.version == version) {
        signJsCode = cached.code;
        // java.log("[+] 缓存命中: " + version);
      } else {
        // java.log("[+] 版本过期: " + cached.version + " -> " + version);
        cache.delete(cacheKey);
      }
    } catch (e) {
      cache.delete(cacheKey);
    }
  }

  if (!signJsCode) {
    signJsCode = String(java.ajax(signJsUrl));
    cache.put(cacheKey, JSON.stringify({
      version: version,
      code: signJsCode
    }), 86400);
    // java.log("[+] 网络拉取: " + version);
  }

  eval(signJsCode);
  // java.log("[+] __SIGN_DECOY = " + window.__SIGN_DECOY);

  var testS = window.__SIGN.f(__enc("test"), t, 12345);
  if (testS === "00000000") {
    // java.log("[-] 环境检测失败");
    cache.delete(cacheKey);
    return;
  }

  var ts = Math.floor(Date.now() / 1000);
  var kw = __enc(key);
  var s = window.__SIGN.f(kw, t, ts);

  // java.log("[+] keyword=" + key + " _ts=" + ts + " _s=" + s);

  var postBody = "_t=" + __enc(t)
    + "&_ts=" + ts
    + "&_s=" + __enc(s)
    + "&keyword=" + kw;

  var actionMatch = homeHtml.match(/action=["'](\/\?action=\w+)["']/);
  var action = actionMatch ? actionMatch[1] : "";
  if (!action) return;

  return host + action + "," + JSON.stringify({
    method: "POST",
    body: postBody
  });
})();

