@js:(function(){
function getMainUrl(jsonStr) {
  try {
    var data = JSON.parse(String(jsonStr));
    if (data.data && Array.isArray(data.data) && data.data.length > 0) {
      var first = data.data[0];
      if (first && first.main_url) return first.main_url;
    }
    var infos = (data.data && data.data.video_model_infos) || [];
    var i;
    var j;
    var info;
    var model;
    var videoList;
    for (i = 0; i < infos.length; i++) {
      info = infos[i];
      if (!info.video_model) continue;
      model = JSON.parse(info.video_model);
      videoList = model.video_list || [];
      for (j = 0; j < videoList.length; j++) {
        if (videoList[j] && videoList[j].main_url) return videoList[j].main_url;
      }
    }
  } catch (e) {
    return null;
  }
  return null;
}
var currentUrl = (typeof chapter !== "undefined" && chapter && chapter.url) ? chapter.url : ((typeof baseUrl !== "undefined" && baseUrl) ? baseUrl : "");
var itemMatch = String(currentUrl).match(/item_id=(\d+)/);
var itemId = itemMatch ? itemMatch[1] : String(currentUrl).replace(/[^0-9]/g, "");
if (itemId === "") return "未找到章节ID";
var playinfoUrl = "https://reading.snssdk.com/reading/reader/audio/playinfo/?tone_id=0&item_ids=" + itemId + "&pv_player=-1&aid=3040&device_platform=android";
var errorMessage = "";
try {
  var signedHeaders = fanqieSignHeaders(playinfoUrl, null);
  var responseBody = java.connect(playinfoUrl, JSON.stringify(signedHeaders)).body();
  var audioUrl = getMainUrl(responseBody);
  if (audioUrl) return audioUrl;
} catch (e2) {
  errorMessage = e2.message || String(e2);
}
return errorMessage ? "获取音频失败：" + errorMessage : "未找到音频链接";
})()

