function checkClickRateLimit(lastCallKey) {
    let { cache } = this;
    let lastCallTime = cache.getFromMemory(lastCallKey) || 0;
    let currentTime = Date.now();
    if (currentTime - lastCallTime < 1000) {
        return false;
    }
    cache.putMemory(lastCallKey, currentTime);
    return true;
}

function handleCommentClick(sourceType, bid, cid, para, date, cacheKey) {
    let { cache } = this;
    let isModifiedVersion = checkEnv.call(this);
    let isQingRead = isQRead.call(this);

    if (!isModifiedVersion && !isQingRead) {
        let mname = cacheKey;
        let load = (cache.getFromMemory(mname) ?? "-").split("-");
        if (load[0] != "1" || load[1] != date) {
            cache.putMemory(mname, "1-" + date);
            return;
        }
        let lastCallKey = `last_call_${sourceType}_${bid}_${cid}_${para}`;
        if (!checkClickRateLimit.call(this, lastCallKey)) {
            return;
        }
    }

    let commentUrl = buildCommentUrl.call(this, sourceType, bid, cid, para);
    let title = isModifiedVersion ? getCommentSourceName(sourceType) + "段评" : (cache.getFromMemory(cacheKey + "-text") ?? getCommentSourceName(sourceType) + "段评");
    startCommentBrowser.call(this, commentUrl, title);
}

function getComments(content, bid, cid, sourceType = 'fq', contentMd5 = null, extraParams = {}) {
    let { java, cache, source } = this;

    if (content == null || content == undefined) {
        return '';
    }
    if (typeof content !== 'string') {
        try {
            content = String(content);
        } catch (e) {
            return '';
        }
    }

    let apiBase = getParagraphApiUrl.call(this);

    try {
        let lines = content
            .replace(new RegExp('(<img[^>]*?>)\n', 'g'), "$1")
            .split("\n")
            .filter(line => line && line.trim());

        if (lines.length == 0) {
            return wrapContentForIOS.call(this, content);
        }

        let isModifiedVersion = checkEnv.call(this);
        let isQingRead = isQRead.call(this);
        let isIOS = deviceType.call(this);

        let apiUrl = buildParagraphUrl.call(this, apiBase, sourceType, bid, cid, contentMd5, extraParams);
        if (!apiUrl) {
            return wrapContentForIOS.call(this, content);
        }

        let response;
        try {
            response = java.ajax(apiUrl);
        } catch (e) {
            return wrapContentForIOS.call(this, content);
        }

        if (!response || (typeof response == 'string' && response.trim() == '')) {
            return wrapContentForIOS.call(this, content);
        }

        let result;
        try {
            result = JSON.parse(response);
        } catch (e) {
            return wrapContentForIOS.call(this, content);
        }

        if (!result || result.code !== 0 || !result.data || !result.data.list) {
            let msg = (result && result.msg) ? result.msg : '请求失败';
            //java.toast(msg);
            return wrapContentForIOS.call(this, content);
        }

        let paragraphList = result.data.list;
        if (!Array.isArray(paragraphList) || paragraphList.length == 0) {
            return wrapContentForIOS.call(this, content);
        }

        let reviews = [];
        let chapterEndData = null;

        if (sourceType == 'qd') {
            try {
                if (result.data.reviews && Array.isArray(result.data.reviews)) {
                    reviews = result.data.reviews;
                }
            } catch (e) {
                reviews = [];
            }

            try {
                let host = getServerHost.call(this);
                let authorUrl = host + '/qd_comment?action=comments&bid=' + bid + '&cid=' + cid + '&para=1&author=1';
                let authorResponse;
                try {
                    authorResponse = java.ajax(authorUrl);
                } catch (e) {
                    authorResponse = null;
                }

                if (authorResponse) {
                    let authorData;
                    try {
                        authorData = JSON.parse(authorResponse);
                    } catch (e) {
                        authorData = null;
                    }

                    if (authorData) {
                        const activity = authorData?.Data?.Getchapteractivity;

                        if (activity && activity.AuthorName) {
                            var authorName = activity.AuthorName || "";
                            var authorSay = activity.AuthorComments || "";
                            var authorExpect = activity.AskMonthTicket?.AuthorExpectText || "";
                            var displayText = authorSay || authorExpect || "";

                            if (authorName && displayText) {
                                authorName = authorName.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
                                displayText = displayText.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

                                var textLines = [];
                                var temp = displayText;
                                var maxChars = 30;
                                while (temp.length > maxChars) {
                                    textLines.push(temp.substring(0, maxChars));
                                    temp = temp.substring(maxChars);
                                }
                                if (temp.length > 0) textLines.push(temp);

                                var textHeight = textLines.length * 30;
                                var totalHeight = 60 + textHeight;
                                var avatarChar = authorName.charAt(0);
                                var avatarColor = "#FF6B6B";

                                var svg = '<svg viewBox="0 0 700 ' + totalHeight + '" xmlns="http://www.w3.org/2000/svg" style="display:block;margin-bottom:8px;width:100%;max-width:700px;height:auto;">\n';
                                svg += '<rect x="0" y="0" width="700" height="' + totalHeight + '" fill="rgba(255,68,68,0.04)" rx="12" stroke="#FF4444" stroke-width="0.3"/>\n';
                                svg += '<circle cx="50" cy="38" r="22" fill="' + avatarColor + '"/>\n';
                                svg += '<text x="50" y="44" font-size="20" text-anchor="middle" font-weight="700" fill="#FFFFFF">' + avatarChar + '</text>\n';
                                svg += '<text x="86" y="30" font-size="17" font-weight="700" fill="#333333">' + authorName + '</text>\n';
                                svg += '<text x="' + (86 + authorName.length * 17 + 6) + '" y="30" font-size="14" font-weight="500" fill="#FF4444">作家的话</text>\n';

                                textLines.forEach(function(line, idx) {
                                    svg += '<text x="86" y="' + (60 + idx * 30) + '" font-size="18" font-weight="400" fill="#666666">' + line + '</text>\n';
                                });

                                svg += '</svg>';

                                var authorSvgBase64 = java.base64Encode(svg);
                                var authorDataUrl = 'data:image/svg+xml;base64,' + authorSvgBase64 + ',{"style":"FULL"}';
                                lines.push('<img src="' + authorDataUrl + '" />');
                            }
                        }
                    }
                }
            } catch (e) {}

            try {
                let host = getServerHost.call(this);
                let chapterEndUrl = host + '/paras/proxy_paragraph?bid=' + bid + '&cid=' + cid;
                let chapterEndResponse;
                try {
                    chapterEndResponse = java.ajax(chapterEndUrl);
                } catch (e) {
                    chapterEndResponse = null;
                }

                if (chapterEndResponse) {
                    let chapterEndResult;
                    try {
                        chapterEndResult = JSON.parse(chapterEndResponse);
                    } catch (e) {
                        chapterEndResult = null;
                    }

                    if (chapterEndResult) {
                        const endActivity = chapterEndResult?.Data?.Getchapteractivity;
                        const endComments = chapterEndResult?.Data?.Getchapterendcomments;
                        if (endActivity && endComments) {
                            chapterEndData = {
                                totalCount: endComments.TotalCount || 0,
                                authorName: endActivity.AuthorName || '',
                                authorExpectText: endActivity.AskMonthTicket?.AuthorExpectText || '',
                                commentList: endComments.DataList || []
                            };
                        }
                    }
                }
            } catch (e) {}
        }

        let reviewsByParagraph = {};
        try {
            reviews.forEach(review => {
                let paraId = review.paragraph_id;
                if (!reviewsByParagraph[paraId]) {
                    reviewsByParagraph[paraId] = [];
                }
                reviewsByParagraph[paraId].push(review);
            });
        } catch (e) {}

        lines = lines.map(line => {
            if (typeof line !== 'string') {
                try {
                    return String(line);
                } catch (e) {
                    return '';
                }
            }
            return line;
        });

        let hasTitleComment = false;
        let titleCommentData = null;

        paragraphList.forEach((item, index) => {
            let paraId = item.paragraph_id || item.paragraphId;
            let count = item.comment_count || item.textCount || 0;
            let hot = (item.hot == 1 || item.is_hot_comment == 1 || item.isHotComment == true);
            if (count <= 0) return;

            let lineIndex;
            if (sourceType == 'qq') {
                if (paraId == 0) {
                    hasTitleComment = true;
                    titleCommentData = item;
                    return;
                }
                lineIndex = parseInt(paraId) - 1;
            } else if (sourceType == 'qd') {
                if (paraId == -1) {
                    hasTitleComment = true;
                    titleCommentData = item;
                    return;
                }
                lineIndex = parseInt(paraId) - 1;
            } else if (sourceType == 'qm') {
                lineIndex = index;
            } else {
                lineIndex = sourceType == 'jj' ? parseInt(paraId) - 1 : parseInt(paraId);
            }

            if (lineIndex < 0 || lineIndex >= lines.length) return;

            if (typeof lines[lineIndex] !== 'string') return;

            if (/<img[^>]*>/i.test(lines[lineIndex])) {
                return;
            }

            if (sourceType == 'fq') {
                let textOnly = String(lines[lineIndex])
                    .replace(new RegExp('<[^>]*>', 'g'), '')
                    .replace(/&nbsp;/g, ' ')
                    .trim();
                if (!textOnly) {
                    return;
                }
                if (!isModifiedVersion && !isQingRead) {
                    cache.putMemory(`fq-${bid}-${cid}-${paraId}-text`, textOnly);
                }
            }

            if (!isModifiedVersion && !isQingRead && sourceType != 'fq') {
                let cacheKey = `${sourceType}-${bid}-${cid}-${paraId}-text`;
                cache.putMemory(cacheKey, lines[lineIndex]);
            }

            let color = hot ? "#f06060" : getCommentIconColor.call(this);
            let commentTag = createSvg.call(this, count, color, bid, cid, paraId, sourceType);

            let reviewTag = '';
            if (sourceType == 'qd' && reviewsByParagraph[paraId]) {
                reviewTag = createGodReviewSvg.call(this, reviewsByParagraph[paraId], bid, cid, paraId);
            }

            if (isIOS) {
                lines[lineIndex] += commentTag;
                if (reviewTag) {
                    lines[lineIndex] += '<br>' + reviewTag;
                }
            } else {
                if (commentTag.startsWith('data:image')) {
                    lines[lineIndex] += `<img src="${commentTag}">`;
                } else {
                    lines[lineIndex] += commentTag;
                }
                if (reviewTag) {
                    if (reviewTag.startsWith('data:image')) {
                        lines[lineIndex] += '\n' + `<img src="${reviewTag}">`;
                    } else {
                        lines[lineIndex] += '\n' + reviewTag;
                    }
                }
            }
        });

        if (hasTitleComment && titleCommentData) {
            let titleCount = titleCommentData.comment_count || titleCommentData.textCount || 0;
            let titleHot = (titleCommentData.hot == 1 || titleCommentData.is_hot_comment == 1 || titleCommentData.isHotComment == true);
            let color = titleHot ? "#f06060" : getCommentIconColor.call(this);
            let titleBubble = createSvg.call(this, titleCount, color, bid, cid, 0, sourceType);
            cache.put(bid + "_" + cid, titleBubble);
        }

        let resultContent = lines.join("\n");
        if (sourceType == 'qd' && chapterEndData && chapterEndData.totalCount > 0) {
            let chapterEndSvg = createChapterEndSvg.call(this, bid, cid, chapterEndData.totalCount, chapterEndData.authorName, chapterEndData.authorExpectText, chapterEndData.commentList);
            resultContent += chapterEndSvg;
        }

        return wrapContentForIOS.call(this, resultContent);
    } catch (e) {
        return wrapContentForIOS.call(this, content);
    }
}

